"""Reproducible synthetic corpus authoring; never run automatically by evaluation.

This corpus is held out from production development at its first frozen run.
It is not independently authored, actuarial guidance, or expert-labeled data.
"""
import json
from pathlib import Path

ROOT = Path(__file__).with_name("holdout")

# Shared application form prose is intentionally realistic boilerplate. The
# case-specific schedules and rules below carry the discriminating information.
