GUIDE_CONTEXT = [
    "This is an invented evaluation manual for a synthetic account. The assessment date is 30 September 2026. The manual contains three independently evaluable underwriting rules, distributed among ordinary explanatory sections. Apply every substantive rule to the named applicant and current observations. Administrative descriptions explain evidence handling; they are not additional underwriting outcomes. A positive credit or favorable treatment denotes a strength. A referral, adverse treatment, or requirement to decline denotes a concern. These vocabulary definitions apply throughout this document, including rules that do not repeat an outcome label. They do not establish that any applicant satisfies a rule.",
    "Read the whole rule together with its scope and stated exception. An exception changes the application of that particular rule; it does not erase a different independent rule. The date of an observation determines which period it describes. Document order is a filing convention and does not alone establish authority. An explicit correction that identifies an earlier entry can supersede that entry. Without such a correction, equally authoritative incompatible current observations remain unresolved. A planned improvement does not establish present completion. A quoted price for work does not demonstrate that the work has been done. Administrative correspondence does not replace a technical measurement.",
    "When evaluating a numerical threshold, preserve its unit, denominator, and comparison operator. A threshold stated as strictly greater than a value excludes equality. A threshold stated as at least a value includes equality. Counts from different populations cannot be combined without a documented relationship. A percentage requiring all members of a population cannot be established by observing a sample unless the rule explicitly permits sampling. A quantity that has not been reported remains unknown. Absence of an inspection record does not prove either a successful inspection or a failed inspection. Distinguish an unanswered question from affirmative evidence that a condition is false.",
    "Each rule stands on the applicant evidence relevant to its subject. A favorable observation about an office process does not establish a technical control in the operating business. Likewise, adverse historical observations do not necessarily describe the present state when a supported correction or completed change has been documented. Keep independent entities separate when more than one qualifies under a rule. Two citations corroborating the same observation need not create two findings. When contradictory observations concern the same entity and date, retain both in the assessment rather than treating them as independent qualifying events. This manual supplies no tie-breaking preference based on page position.",
    "The source packet may contain working notes, completed exhibits, and administrative descriptions. The purpose of retaining surrounding material is to preserve qualifiers and distinguish observations from proposals. A summary may be shorter than the supporting exhibit and should not be used to invent details absent from it. The policy vocabulary above describes how rule outcomes are recorded; the condition within each rule still has to be established. No outcome is implied by the presence of a heading alone. Record unanswered evidence questions as such, and keep the explanation tied to the actual observations, applicable rule, and any relevant exception or limitation.",
]

def rule(quote, classification, status, support, groups, rationale, implicit=False):
    return dict(quote=quote, classification=classification, status=status, support=support,
                finding_groups=groups, rationale=rationale, implicit=implicit)

CASES = [
    dict(id="property", title="Alder cold-storage buildings", mode="explicit", narrative="Alder operates three refrigerated buildings: North, South, and East. A roof-condition survey and a sprinkler inspection form were supplied with the renewal. Buildings share a mailing address but retain independent service records. Food stock values and refrigeration service budgets are administrative context and are not roof-age measurements.", rules=[
        rule("[concern] A cold-storage building whose roof is more than 25 years old is a concern unless a complete roof replacement has been documented within the last 2 years.", "concern", "matched", ["North building roof age: 28 years; no complete replacement has occurred.", "South building roof age: 31 years; no complete replacement has occurred.", "East building had a complete roof replacement on 1 March 2026; its roof age is 0 years."], [[0], [1]], "Identify North and South separately: 28 and 31 exceed 25, with no replacement exception. East is excluded by its documented replacement/current age."),
        rule("Current sprinkler inspection certificates with no outstanding deficiencies for every cold-storage building are a strength.", "strength", "matched", ["Current sprinkler certificates cover North, South, and East; each records no outstanding deficiencies."], [[0]], "All three buildings have current certificates and no deficiencies; the all-buildings requirement is established."),
        rule("[concern] A cold-storage building with combustible insulated wall panels is a concern unless a current independent fire-engineering certification approves those panels.", "concern", "no_match", ["All three buildings have combustible insulated wall panels; current independent fire-engineering certification approves those panels in North, South, and East."], [], "The panels meet the trigger, but current independent approval for all three makes the stated exception apply; do not claim the panels are noncombustible.")]),
    dict(id="cyber", title="Birch hosted payroll services", mode="mixed", narrative="Birch provides hosted payroll processing for employer clients. The renewal contains an access inventory and recovery exercise log. A customer-facing marketing sheet discusses encryption and service availability but is not the privileged-access inventory. Recovery testing used an isolated copy of the payroll application and did not interrupt customer processing.", rules=[
        rule("[strength] MFA on every active privileged account is a strength.", "strength", "no_match", ["The current privileged-access inventory contains 24 active accounts.", "MFA is enabled for 23 of the 24 active privileged accounts; the remaining account is an active emergency administrator without MFA."], [], "23/24 is not every account. The active emergency account is in scope and there is no exception; this is affirmative failure, not missing evidence."),
        rule("A successful isolated recovery test within the last 90 days is a strength.", "strength", "matched", ["An isolated payroll recovery test succeeded on 15 August 2026; the test log records restored data and a successful application start."], [[0]], "15 August is 46 days before 30 September, within 90; a successful isolated test is recorded."),
        rule("Refer any account that stores unencrypted portable copies of payroll data for adverse treatment.", "concern", "matched", ["Two portable USB drives currently hold unencrypted payroll exports used by the support team."], [[0]], "Unencrypted portable payroll copies meet the referral rule; the guideline's vocabulary maps adverse treatment to concern.", True)]),
    dict(id="fleet", title="Cedar regional haulage", mode="mixed", narrative="Cedar operates a regional delivery fleet under its own motor authority. Driver and maintenance records have different responsible managers. Driver reviews are recorded per active driver, while defect records refer to individual vehicles. The commercial schedule includes five leased passenger vehicles and eight heavy goods vehicles. Vehicle purchase budgets are forecasts and do not document repairs.", rules=[
        rule("[concern] A heavy goods vehicle with an unresolved brake defect is a concern.", "concern", "insufficient_evidence", ["Inspector A's signed 29 September 2026 inspection of vehicle H7 records an unresolved brake defect.", "Inspector B's equally authoritative signed 29 September 2026 inspection of vehicle H7 records no brake defect; neither report corrects the other.", "The other seven heavy goods vehicles have no brake defects; H7 is the only disputed vehicle."], [], "The equally authoritative H7 records conflict for the same date with no correction; abstain rather than select one report or emit a settled concern."),
        rule("[strength] Completed annual driving-record reviews for all active drivers are a strength.", "strength", "insufficient_evidence", ["There are 18 active drivers. The broker has requested, but has not received, the annual driving-record review register."], [], "The register is missing. This does not prove that reviews were not performed; evidence is insufficient to establish all-driver coverage."),
        rule("Give favorable treatment when verified telematics show a harsh-braking rate below 2 events per 1000 miles across the active fleet.", "strength", "matched", ["The verified active-fleet telematics report records 54 harsh-braking events over 36000 miles during the reporting period."], [[0]], "54 / 36000 * 1000 = 1.5, strictly below 2. Favorable treatment maps to strength.", True)]),
    dict(id="manufacturing", title="Dune precision fabrication", mode="implicit", narrative="Dune fabricates components for industrial customers. The operating floor includes one production press and a finishing area. Maintenance records are kept separately from hot-work permits. A vendor's proposed modernization package is included for budgeting, but the current operating controls are described in the technical exhibits. Historical equipment brochures do not establish the present machine configuration.", rules=[
        rule("Decline operations using a production press without an interlocked guard.", "concern", "matched", ["Production press P4 remains in daily use without an interlocked guard; the proposed retrofit has not been ordered."], [[0]], "P4 is in use and unguarded; a proposed retrofit is not completion. Decline maps to concern.", True),
        rule("Allow positive credit when completed hot-work permits and fire-watch records cover every hot-work job in the last 12 months.", "strength", "matched", ["The complete 12-month hot-work register lists 9 jobs; signed permits and completed fire-watch records are attached for all 9."], [[0]], "All 9 jobs have both required records over the required period; positive credit maps to strength.", True),
        rule("Refer a finishing area with flammable liquids in open containers, except while the liquids are inside an approved enclosed dispensing system.", "concern", "no_match", ["The finishing-area liquids are entirely inside an approved enclosed dispensing system; no containers are open outside it."], [], "The recorded enclosed system meets the exception and there is no open-container exposure outside it; no concern should be emitted.", True)]),
    dict(id="hospitality", title="Elm urban hotel", mode="explicit", narrative="Elm operates an urban hotel with a ground-floor restaurant. The kitchen has a named suppression system. The site plan includes an enclosed decorative fountain in the lobby but no recreational water facilities. A cash-flow summary distinguishes unrestricted cash from restricted customer deposits. The restaurant manager and finance director signed their respective exhibits independently.", rules=[
        rule("[concern] A hotel kitchen suppression system with service overdue by more than 30 days is a concern.", "concern", "no_match", ["The kitchen suppression system's scheduled service date was 31 August 2026. It remains unserviced as of 30 September 2026, exactly 30 days overdue."], [], "Exactly 30 days does not exceed 30; preserve the strict greater-than threshold despite the service being overdue."),
        rule("[concern] An unfenced guest swimming pool is a concern; this rule applies only to properties operating a guest swimming pool.", "concern", "not_applicable", ["The property does not operate a guest swimming pool. The enclosed lobby fountain is decorative and unavailable for swimming."], [], "No guest pool means the rule is out of scope; do not label this an in-scope negative or treat the fountain as a pool."),
        rule("Unrestricted cash covering at least 6 months of fixed operating costs is a strength.", "strength", "matched", ["Unrestricted cash is 780000 dollars; fixed operating costs are 120000 dollars per month. Restricted customer deposits are excluded from the cash figure."], [[0]], "780000/120000 = 6.5 months, at least 6; restricted deposits were excluded and should not be added.")]),
    dict(id="contractor", title="Fir mechanical installations", mode="mixed", narrative="Fir performs mechanical installations at customer premises. It subcontracts electrical and access work when required. The project schedule distinguishes current work from completed jobs. Certificates of insurance are filed by subcontractor, while design responsibilities appear in executed contracts. The company has no separate design subsidiary, but contract language can still assign design responsibility to the operating entity.", rules=[
        rule("[strength] Current insurance certificates for every active subcontractor are a strength.", "strength", "matched", ["The active subcontractor register contains 4 firms; all 4 have current insurance certificates covering the proposed policy period."], [[0]], "All four active subcontractors are covered by current certificates; the population and validity period are established."),
        rule("Refer contracts that transfer structural design responsibility to the applicant unless an executed agreement delegates that responsibility to an insured licensed engineer.", "concern", "matched", ["The current Riverside contract transfers structural design responsibility to Fir. No executed agreement delegates that responsibility to an engineer."], [[0]], "Design responsibility is contractually assumed and no executed delegation supports the exception; referral maps to concern.", True),
        rule("Allow positive credit for a documented rescue drill for every crew scheduled for confined-space entry during the policy period.", "strength", "insufficient_evidence", ["Two crews are scheduled for confined-space entry during the policy period; rescue-drill records have been requested but are not yet supplied."], [], "Two crews are in scope but drill records are missing; absence of records does not prove drills did not happen or establish positive credit.", True)]),
]


def main():
    ROOT.mkdir(exist_ok=True)
    docs = ROOT / "documents"
    docs.mkdir(exist_ok=True)
    dataset = {"version": 1, "description": "First-use synthetic holdout against frozen production implementation; not expert labeled. Gold and rationale are scoring-only.", "cases": []}
    for case in CASES:
        guideline = [f"# {case['title']}: evaluation manual", GUIDE_CONTEXT[0], case["narrative"]]
        application = [f"# {case['title']}: renewal submission", case["narrative"]]
        for i, (heading, text) in enumerate(APPLICATION_SECTIONS):
            application.extend([f"## {heading}", text])
            if i in (1, 6, 10):
                r = case["rules"][(1, 6, 10).index(i)]
                application.extend(["### Technical exhibit", *r["support"]])
        for i, r in enumerate(case["rules"]):
            guideline.extend([f"## Review section {i+1}", GUIDE_CONTEXT[i+1], r["quote"]])
        guideline.extend(["## Reading the complete packet", GUIDE_CONTEXT[4]])
        guide_name, app_name = case["id"] + "-guideline.md", case["id"] + "-application.md"
        # Blank separators keep physical paragraphs and evidence locators stable.
        guide_text, app_text = "\n\n".join(guideline) + "\n", "\n\n".join(application) + "\n"
        (docs / guide_name).write_text(guide_text, encoding="utf-8")
        (docs / app_name).write_text(app_text, encoding="utf-8")
        gold = []
        for i, r in enumerate(case["rules"], 1):
            gold.append({**r, "id": f"G{i}", "support": [[app_name, f"line:{app_text.splitlines().index(q)+1}", q] for q in r["support"]]})
        dataset["cases"].append({"id": case["id"], "title": case["title"], "mode": case["mode"], "guideline": guide_name, "documents": [app_name], "expected": gold})
    (ROOT / "cases.json").write_text(json.dumps(dataset, indent=2) + "\n", encoding="utf-8")
    for path in sorted(docs.iterdir()):
        print(path.name, len(path.read_text(encoding="utf-8").split()), "words")


if __name__ == "__main__":
    main()
